      "version": 1,
      "contentJson": "{\"freshnessTargetMinutes\":1440,\"maxNullRatePct\":8,\"rules\":[{\"alertRoute\":\"DATA_ENGINEER\",\"attribute\":\"position_id\",\"dimension\":\"FRESHNESS\",\"expression\":\"max(loaded_at) >= now() - interval '1440 minutes'\",\"id\":\"QR-FRESH\",\"severity\":\"HIGH\",\"threshold\":1440,\"unit\":\"minutes\"},{\"alertRoute\":\"DATA_STEWARD\",\"attribute\":\"position_id\",\"dimension\":\"COMPLETENESS\",\"expression\":\"null_rate(position_id) <= 1\",\"id\":\"QR-COMPLETE\",\"severity\":\"HIGH\",\"threshold\":1,\"unit\":\"%\"},{\"alertRoute\":\"DATA_ENGINEER\",\"attribute\":\"position_id\",\"dimension\":\"UNIQUENESS\",\"expression\":\"count(*) = count(distinct position_id)\",\"id\":\"QR-UNIQUE\",\"severity\":\"CRITICAL\",\"threshold\":100,\"unit\":\"%\"}]}",
